## Why This Is Asked
Tests data-structure augmentation in a Trie to support prefix queries and k-th item retrieval with weights, mirroring autocomplete and ranking systems.

## Key Concepts
- Trie augmentation with per-subtree weights
- Prefix sum queries in O(length of prefix)
- K-th word selection within a prefix using cumulative weights
- Handling duplicates and deletions robustly

## Code Example
```javascript
class TrieNode { constructor(){ this.next=new Map(); this.subWeight=0; this.endWeight=0; this.isWord=false; } }
class Trie {
  constructor(){ this.root=new TrieNode(); }
  insert(word,w){ let node=this.root; node.subWeight+=w; for(let ch of word){ if(!node.next.has(ch)) node.next.set(ch,new TrieNode()); node=node.next.get(ch); node.subWeight+=w; } node.isWord=true; node.endWeight+=w; }
  delete(word,w){ this.insert(word,-w); }
  sumPrefix(prefix){ let node=this.root; for(let ch of prefix){ if(!node.next.has(ch)) return 0; node=node.next.get(ch); } return node.subWeight; }
  kthWord(prefix,k){ let node=this.root; for(let ch of prefix){ if(!node.next.has(ch)) return null; node=node.next.get(ch); }
    function dfs(n, path){ if(n.isWord && n.endWeight>0){ if(--k===0) return path; }
      for(let c of [...n.next.keys()].sort()){ let child=n.next.get(c); if(child.subWeight>=k){ const res=dfs(child, path+c); if(res) return res; } else { k-=child.subWeight; } }
      return null; }
    return dfs(node, prefix);
  }
}
```

